import type { UpdateLoadData } from '../core/load.repository';

/** Every document a load carries. */
export const LOAD_DOCUMENT_TYPES = [
  'invoice', // the shipper's goods invoice
  'eway_bill',
  'signed_lr', // the signed lorry receipt photographed at loading
  'elr', // the e-LR PDF generated by the system
  'load_memo', // the accepted load memo's PDF
  'loading_photo',
  'weighing_slip',
  'pod_front',
  'pod_back',
  'stamped_invoice', // optional with the POD: the invoice stamped by the receiver
  'damage_photo',
  'transporter_invoice', // own transporter / indent, stage 11
  'charge_proof', // with a charge on an own-transporter or indent load
  'payment_proof', // the advice or screenshot with a recorded payment
  'driver_licence_front', // Loadsmart loads: Placement collects these with the driver
  'driver_licence_back',
  'rc_copy',
  'claim_evidence', // Customer support's evidence on a Loadsmart claim
] as const;
export type LoadDocumentType = (typeof LOAD_DOCUMENT_TYPES)[number];

/** How the file reached us. */
export const LOAD_DOCUMENT_SOURCES = [
  'web',
  'driver_app',
  'console',
  'whatsapp',
  'system',
  'backfill',
] as const;
export type LoadDocumentSource = (typeof LOAD_DOCUMENT_SOURCES)[number];

/** `not_required`: nobody has to check it (the shipper's own uploads on their own loads). The
 *  POD's documents follow the POD decision; a Loadsmart load's papers wait for Loadsmart. */
export const LOAD_DOCUMENT_REVIEW_STATUSES = [
  'not_required',
  'pending',
  'approved',
  'rejected',
] as const;
export type LoadDocumentReviewStatus = (typeof LOAD_DOCUMENT_REVIEW_STATUSES)[number];

export const DOCUMENT_REVIEW_DECISIONS = ['approved', 'rejected'] as const;
export type DocumentReviewDecision = (typeof DOCUMENT_REVIEW_DECISIONS)[number];

/** The load column that points at each type's current file — kept as a pointer so the stage
 *  rules and screens read the load as before — and the number stored beside it, if any. Types
 *  with no column (the driver's papers) live only in the register. */
export const DOCUMENT_COLUMNS: Partial<
  Record<
    LoadDocumentType,
    { column: keyof UpdateLoadData; numberColumn?: keyof UpdateLoadData; multiple?: true }
  >
> = {
  invoice: { column: 'invoiceFileKey', numberColumn: 'invoiceNumber' },
  eway_bill: { column: 'ewayBillFileKey', numberColumn: 'ewayBillNumber' },
  signed_lr: { column: 'elrFileKey', numberColumn: 'elrNumber' },
  elr: { column: 'elrDocumentFileKey', numberColumn: 'elrNumber' },
  loading_photo: { column: 'loadingPhotoFileKeys', multiple: true },
  weighing_slip: { column: 'weighingSlipFileKey' },
  pod_front: { column: 'podFileKey' },
  pod_back: { column: 'podBackFileKey' },
  damage_photo: { column: 'damagePhotoKey' },
  transporter_invoice: {
    column: 'transporterInvoiceFileKey',
    numberColumn: 'transporterInvoiceNumber',
  },
};

/** Extra files that build up as a set — a new one never supersedes the last. */
export const SET_DOCUMENT_TYPES: readonly LoadDocumentType[] = ['charge_proof', 'claim_evidence'];

/** Decided with the POD (LoadService.reviewPod), never on their own. */
export const POD_DOCUMENT_TYPES: readonly LoadDocumentType[] = [
  'pod_front',
  'pod_back',
  'stamped_invoice',
  'damage_photo',
];

/** Checked by Loadsmart on a Loadsmart load before it moves on. */
export const LOADSMART_REVIEWED_TYPES: readonly LoadDocumentType[] = [
  'invoice',
  'eway_bill',
  'signed_lr',
  'loading_photo',
  'weighing_slip',
  'driver_licence_front',
  'driver_licence_back',
  'rc_copy',
];

/** Who uploaded it and how. A driver-app upload carries the driver, not a user. */
export interface DocumentActor {
  userId: string | null;
  driverId?: string | null;
  source: LoadDocumentSource;
}

/** A file outside the load's own columns — the driver's papers on a Loadsmart load. */
export interface ExtraDocument {
  docType: LoadDocumentType;
  fileKey: string;
}

export interface LoadDocumentView {
  id: string;
  docType: LoadDocumentType;
  version: number;
  fileKey: string;
  downloadUrl: string | null;
  current: boolean;
  supersedesId: string | null;
  supersededAt: string | null;
  source: LoadDocumentSource;
  uploadedBy: string | null;
  uploadedByDriverId: string | null;
  uploadedAt: string;
  reviewStatus: LoadDocumentReviewStatus;
  rejectionReason: string | null;
  reviewedBy: string | null;
  reviewedAt: string | null;
  extracted: Record<string, unknown> | null;
}
